123 :   public void process(Node externs, Node root) {
124 :     ScopeCreator scopeCreator = createScopeCreator();
125 :     // Don't run externs-checking in sanity check mode. Normalization will
126 :     // remove duplicate VAR declarations, which will make
127 :     // externs look like they have assigns.
128 :     if (!sanityCheck) {
129 :       NodeTraversal traversal = new NodeTraversal(
130 :           compiler, new NameRefInExternsCheck(), scopeCreator);
131 :       traversal.traverse(externs);
132 :     }
133 : 
134 :     NodeTraversal t = new NodeTraversal(compiler, this, scopeCreator);
135 :     t.traverseRoots(Lists.newArrayList(externs, root));
136 :     for (String varName : varsToDeclareInExterns) {
137 :       createSynthesizedExternVar(varName);
138 :     }
139 :   }"

"113 :   private ScopeCreator createScopeCreator() {
114 :     if (sanityCheck) {
115 :       return new SyntacticScopeCreator(compiler);
116 :     } else {
117 :       return new SyntacticScopeCreator(
118 :           compiler, new RedeclarationCheckHandler());
119 :     }
