"242 :   private void createSynthesizedExternVar(String varName) {
243 :     Node nameNode = IR.name(varName);
244 : 
245 :     // Mark the variable as constant if it matches the coding convention
246 :     // for constant vars.
247 :     // NOTE(nicksantos): honestly, I'm not sure how much this matters.
248 :     // AFAIK, all people who use the CONST coding convention also
249 :     // compile with undeclaredVars as errors. We have some test
250 :     // cases for this configuration though, and it makes them happier.
251 :     if (compiler.getCodingConvention().isConstant(varName)) {
252 :       nameNode.putBooleanProp(Node.IS_CONSTANT_NAME, true);
253 :     }
254 : 
255 :     getSynthesizedExternsRoot().addChildToBack(
256 :         IR.var(nameNode));
257 :     varsToDeclareInExterns.remove(varName);
258 :     compiler.reportCodeChange();
259 :   }"

"266 :     @Override
267 :     public void visit(NodeTraversal t, Node n, Node parent) {
268 :       if (n.isName()) {
269 :         switch (parent.getType()) {
270 :           case Token.VAR:
271 :           case Token.FUNCTION:
272 :           case Token.PARAM_LIST:
273 :             // These are okay.
274 :             break;
275 :           case Token.GETPROP:
276 :             if (n == parent.getFirstChild()) {
277 :               Scope scope = t.getScope();
278 :               Scope.Var var = scope.getVar(n.getString());
279 :               if (var == null) {
280 :                 t.report(n, UNDEFINED_EXTERN_VAR_ERROR, n.getString());
281 :                 varsToDeclareInExterns.add(n.getString());
282 :               }
283 :             }
284 :             break;
285 :           default:
286 :             t.report(n, NAME_REFERENCE_IN_EXTERNS_ERROR, n.getString());
287 : 
288 :             Scope scope = t.getScope();
289 :             Scope.Var var = scope.getVar(n.getString());
290 :             if (var == null) {
291 :               varsToDeclareInExterns.add(n.getString());
292 :             }
293 :             break;
294 :         }
295 :       }
296 :     }"

